BEGIN;

CREATE TABLE IF NOT EXISTS public."DeletionHistory" (
    "DeletionID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EntityType" VARCHAR(20) NOT NULL CHECK ("EntityType" IN ('departments','projects','tasks','tags','accounts')),
    "EntityID" INTEGER NOT NULL CHECK ("EntityID" > 0),
    "EntityName" TEXT NOT NULL,
    "DeletedByID" INTEGER NOT NULL,
    "DeletedAt" TIMESTAMPTZ NOT NULL,
    "UndoUntil" TIMESTAMPTZ NOT NULL,
    "RestoredAt" TIMESTAMPTZ,
    "RestoredByID" INTEGER,
    "Snapshot" JSONB NOT NULL,
    CHECK ("UndoUntil" = "DeletedAt" + INTERVAL '24 hours'),
    CHECK (("RestoredAt" IS NULL) = ("RestoredByID" IS NULL))
);

-- Historical actor IDs deliberately survive account deletion.
CREATE INDEX IF NOT EXISTS "IX_DeletionHistory_DeletedAt" ON public."DeletionHistory" ("DeletedAt" DESC, "DeletionID" DESC);
CREATE INDEX IF NOT EXISTS "IX_DeletionHistory_Type_DeletedAt" ON public."DeletionHistory" ("EntityType", "DeletedAt" DESC);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_DeletionHistory_Pending" ON public."DeletionHistory" ("EntityType", "EntityID") WHERE "RestoredAt" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Tag_TagName_Lower" ON public."Tag" (lower("TagName"));

COMMIT;
